import { CommandPalette } from "@/components/design-for-ai/command-palette";
import { Inbox, Plus } from "lucide-react";

export default function App() {
  return (
    <CommandPalette
      workspace="Fieldwork"
      groups={[
        { id: "nav", label: "Navigation", items: [{ id: "inbox", label: "Go to Inbox", shortcut: ["G", "I"], icon: Inbox }] },
        { id: "do", label: "Actions", items: [{ id: "new", label: "New brief", keywords: ["create"], icon: Plus }] },
